en/index.styles:
.hero--int { min-height: 88vh; display: block; padding-top: 0; }
.hero--int .hero-bg { background-image: url('/assets/images/projects/secom-nangang-complex/photo-01.jpg'); background-position: center 40%; opacity: 0.75; }
.hero--int::after { background: linear-gradient(180deg, rgba(20,35,50,0.78) 0%, rgba(20,35,50,0.68) 48%, rgba(20,35,50,0.84) 100%); }
.hero--int .hero-content { padding-top: 168px; padding-bottom: 56px; }
.hero--int .hero-headline { font-size: clamp(48px, 7vw, 92px); letter-spacing: -2px; margin-bottom: 24px; }
.hero--int .hero-sub-en { font-size: 18px; max-width: 640px; margin-bottom: 40px; color: rgba(255,255,255,0.78); line-height: 1.5; }
.hero--int .hero-actions { margin-bottom: 56px; }
.hero--int .btn-primary { background: var(--accent); border-color: var(--accent); padding: 16px 32px; font-size: 15px; }
.hero--int .btn-primary:hover { background: var(--accent-dark); border-color: var(--accent-dark); }
.hero--int .hero-stats { gap: 56px; padding-top: 36px; border-top: 1px solid rgba(255,255,255,0.14); }
.hero--int .stat-num { font-size: 48px; display: inline-flex; align-items: baseline; gap: 2px; }
.hero--int .stat-num .stat-unit { font-size: 32px; color: var(--accent); font-weight: 700; }
.hero--int .stat-label-en { font-size: 10px; letter-spacing: 1.2px; text-transform: uppercase; }
.logos-bar--int { background: var(--white); border-bottom: 1px solid var(--border); padding: 36px 0; }
.logos-bar--int .logos-grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 20px 0; }
.logos-bar--int .logo-item { flex: 0 0 20%; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 4px; padding: 4px 0; opacity: 0.88; }
.logos-bar--int .logo-item:hover { opacity: 1; }
.logos-bar--int .logo-item .lo-en { font-family: var(--font-en); font-size: 12px; font-weight: 700; letter-spacing: 0.6px; color: var(--brand); line-height: 1.1; text-transform: uppercase; }
.logos-bar--int .logos-bar-label { font-family: var(--font-en); font-size: 10px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--light); text-align: center; margin-bottom: 22px; font-weight: 600; }
.taiwan-wedge { background: var(--brand); color: var(--white); padding: 88px 0; position: relative; overflow: hidden; }
.taiwan-wedge::before { content: ''; position: absolute; top: 0; right: 0; bottom: 0; width: 45%; background-image: url('/assets/images/projects/csun/render-01.jpg'); background-size: cover; background-position: center; opacity: 0.20; pointer-events: none; }
.taiwan-wedge::after { content: ''; position: absolute; top: 0; bottom: 0; right: 35%; width: 30%; background: linear-gradient(90deg, var(--brand) 0%, transparent 100%); pointer-events: none; }
.taiwan-wedge .container { position: relative; z-index: 1; }
.taiwan-wedge .label { color: var(--accent); margin-bottom: 14px; }
.taiwan-wedge h2 { font-family: var(--font-en); font-size: clamp(32px, 4.2vw, 48px); letter-spacing: -1.2px; max-width: 720px; margin-bottom: 20px; line-height: 1.1; }
.taiwan-wedge .lead { max-width: 640px; font-size: 17px; color: rgba(255,255,255,0.72); line-height: 1.65; margin-bottom: 32px; }
.taiwan-wedge .checks { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 14px 28px; max-width: 720px; margin-bottom: 36px; }
.taiwan-wedge .check { display: flex; gap: 12px; align-items: flex-start; font-family: var(--font-en); font-size: 14px; color: rgba(255,255,255,0.82); }
.taiwan-wedge .check .dot { width: 6px; height: 6px; background: var(--accent); border-radius: 50%; margin-top: 8px; flex-shrink: 0; }
.scroll-cue { position: absolute; bottom: 28px; left: 50%; transform: translateX(-50%); font-family: var(--font-en); font-size: 10px; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.45); z-index: 2; display: flex; flex-direction: column; align-items: center; gap: 8px; }
.scroll-cue .line { width: 1px; height: 36px; background: linear-gradient(180deg, rgba(255,255,255,0.40), transparent); }
.project-name { display: flex; flex-direction: column; gap: 2px; line-height: 1.25; margin-bottom: 6px; }
.project-name .name-en { font-family: var(--font-en); font-size: 18px; font-weight: 700; color: var(--white); }
.project-name .name-zh-pn { font-family: var(--font-zh); font-size: 13px; font-weight: 500; color: rgba(255,255,255,0.65); }
.project-name .name-zh { font-family: var(--font-zh); font-size: 18px; font-weight: 700; color: var(--white); }
@media (max-width: 768px) {
  .hero--int .hero-content { padding-top: 110px; }
  .taiwan-wedge::before, .taiwan-wedge::after { display: none; }
  .taiwan-wedge .checks { grid-template-columns: 1fr; }
  .hero--int .hero-stats { gap: 28px; }
}

en/projects.styles:
.project-name { display: flex; flex-direction: column; gap: 2px; line-height: 1.25; margin-bottom: 6px; }
.project-name .name-en { font-family: var(--font-en); font-size: 18px; font-weight: 700; color: var(--white); }
.project-name .name-zh-pn { font-family: var(--font-zh); font-size: 13px; font-weight: 500; color: rgba(255,255,255,0.65); }
.project-name .name-zh { font-family: var(--font-zh); font-size: 18px; font-weight: 700; color: var(--white); }
.project-name .name-en-sub { font-family: var(--font-en); font-size: 13px; font-weight: 500; color: rgba(255,255,255,0.65); }

en/careers.styles:
.careers-banner { background: var(--dark); position: relative; overflow: hidden; padding: 140px 0 80px; }
.careers-banner-bg { position: absolute; inset: 0; background-image: url('/assets/images/projects/kimpton/photo-01.jpg'); background-size: cover; background-position: center 30%; opacity: 0.15; }
.value-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
.value-card { padding: 36px 32px; border: 1px solid var(--border); border-radius: var(--radius); transition: all var(--transition); }
.value-card:hover { border-color: var(--brand); box-shadow: var(--shadow); }
.value-card h3 { font-size: 18px; margin-bottom: 12px; }
.value-card p { font-size: 14px; color: var(--mid); line-height: 1.7; }
@media (max-width: 768px) { .value-grid { grid-template-columns: 1fr; } }

